import pathlib,json,hashlib,sys
sys.path.insert(0,'tools/shared');from test_direct import authenticate_build
out=pathlib.Path(sys.argv[1]);sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest();before=json.loads((out/'inputs.before.json').read_text());after={n:sha(pathlib.Path(n)) for n in before};assert before==after
p=pathlib.Path('.mlf-build/recovery-ghc-O2/receipt.json');r=authenticate_build(p,p.parent/'bin');assert all(sha(p.parent/n)==h for n,h in r['object_inputs'].items());receipt=json.loads((out/'bounded-receipt.json').read_text());assert receipt['complete'] and receipt['exit_code']==0;assert all((out/'artifact'/('unit.'+ext)).is_file() and (out/'artifact'/('unit.'+ext)).stat().st_size>0 for ext in ['mlfci','mlfco','queries']);q=json.loads((out/'artifact/unit.queries').read_text());inventory={str(f.relative_to(out)):{'bytes':f.stat().st_size,'sha256':sha(f)} for f in out.rglob('*') if f.is_file() and f.suffix in ['.mlfci','.mlfco','.mlfq','.queries']};result={'complete':True,'source_unchanged':True,'producer_reauthenticated':True,'producer_receipt_sha256':sha(p),'inferred_groups':q['inferred_groups'],'reused_groups':q['reused_groups'],'native_or_llvm':False,'elapsed_seconds':receipt['elapsed_seconds'],'peak_rss':receipt['peak_group_rss'],'checked_artifact_bytes':sum(v['bytes'] for v in inventory.values()),'artifact_files':len(inventory)};(out/'inputs.after.json').write_text(json.dumps(after,indent=2)+'\n');(out/'output-inventory.json').write_text(json.dumps(inventory,indent=2)+'\n');(out/'result.json').write_text(json.dumps(result,indent=2)+'\n');print(json.dumps(result))
